//! Gmail API v1 implementation.//!//! All API calls go through the host's HTTP capability, which handles//! credential injection and rate limiting. The WASM tool never sees//! the actual OAuth token.use crate::near::agent::host;use crate::types::*;const GMAIL_API_BASE: &str = "https://gmail.googleapis.com/gmail/v1/users/me";/// Make a Gmail API call.fn api_call(method: &str, path: &str, body: Option<&str>) -> Result<String, String> {    let url = format!("{}/{}", GMAIL_API_BASE, path);    let headers = if body.is_some() {        r#"{"Content-Type": "application/json"}"#    } else {        "{}"    };    let body_bytes = body.map(|b| b.as_bytes().to_vec());    host::log(        host::LogLevel::Debug,        &format!("Gmail API: {} {}", method, path),    );    let response = host::http_request(method, &url, headers, body_bytes.as_deref(), None)?;    if response.status < 200 || response.status >= 300 {        let body_text = String::from_utf8_lossy(&response.body);        return Err(format!(            "Gmail API returned status {}: {}",            response.status, body_text        ));    }    if response.body.is_empty() {        return Ok(String::new());    }    String::from_utf8(response.body).map_err(|e| format!("Invalid UTF-8 in response: {}", e))}/// Extract a header value from a Gmail message payload.fn get_header(payload: &serde_json::Value, name: &str) -> String {    payload["headers"]        .as_array()        .and_then(|headers| {            headers.iter().find(|h| {                h["name"]                    .as_str()                    .map(|n| n.eq_ignore_ascii_case(name))                    .unwrap_or(false)            })        })        .and_then(|h| h["value"].as_str())        .unwrap_or("")        .to_string()}/// Extract plain text body from a Gmail message payload./// Walks the MIME parts tree to find text/plain content.fn extract_body(payload: &serde_json::Value) -> String {    // Try direct body first (simple messages)    if let Some(data) = payload["body"]["data"].as_str() {        if let Some(decoded) = base64url_decode(data) {            return decoded;        }    }    // Walk parts for multipart messages    if let Some(parts) = payload["parts"].as_array() {        for part in parts {            let mime_type = part["mimeType"].as_str().unwrap_or("");            if mime_type == "text/plain" {                if let Some(data) = part["body"]["data"].as_str() {                    if let Some(decoded) = base64url_decode(data) {                        return decoded;                    }                }            }            // Recurse into nested parts (e.g., multipart/alternative inside multipart/mixed)            if mime_type.starts_with("multipart/") {                let nested = extract_body(part);                if !nested.is_empty() {                    return nested;                }            }        }        // Fall back to text/html if no text/plain found        for part in parts {            if part["mimeType"].as_str() == Some("text/html") {                if let Some(data) = part["body"]["data"].as_str() {                    if let Some(decoded) = base64url_decode(data) {                        return decoded;                    }                }            }        }    }    String::new()}/// Parse a full message from the API response.fn parse_message(v: &serde_json::Value) -> Message {    let payload = &v["payload"];    let label_ids: Vec<String> = v["labelIds"]        .as_array()        .map(|arr| {            arr.iter()                .filter_map(|l| l.as_str().map(|s| s.to_string()))                .collect()        })        .unwrap_or_default();    Message {        id: v["id"].as_str().unwrap_or("").to_string(),        thread_id: v["threadId"].as_str().unwrap_or("").to_string(),        subject: get_header(payload, "Subject"),        from: get_header(payload, "From"),        to: get_header(payload, "To"),        cc: {            let cc = get_header(payload, "Cc");            if cc.is_empty() {                None            } else {                Some(cc)            }        },        date: get_header(payload, "Date"),        body: extract_body(payload),        snippet: v["snippet"].as_str().unwrap_or("").to_string(),        is_unread: label_ids.iter().any(|l| l == "UNREAD"),        label_ids,    }}/// List messages in the mailbox.